-- public.perform_artifact(p_world uuid, p_uid uuid, p_action text, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.perform_artifact(p_world uuid, p_uid uuid, p_action text, c creature)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_def text := artifact_item(p_action); v_name text; v_age text; v_stat text; v_points int; v_rare text;
        v_traits text[]; v_slot int; v_was text; v_from text; v_tier text; v_now text; v_up boolean;
begin
  if artifact_refusal(p_world, p_uid, p_action, c) is not null then return; end if;
  v_name := lower((select name from item_def where id = v_def));
  if not consume(p_world, p_uid, v_def, 1) then return; end if;

  if p_action = 'use_ancient_comb' then
    -- The start of the stage below, `comb_into` into it, at the pace its keeper's perks age it.
    v_age := age_of(c.born, old_of(c), age_pace(c));
    update creature set born = now() - make_interval(secs => ((case when v_age = 'old' then young_for() else 0 end)
                                                              + comb_into()) / age_pace(c))
     where world_id = p_world and id = c.id;
    perform wtell(p_world, p_uid, case when v_age = 'old'
      then upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': now just grown, full pace and pull.'
      else upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': now newborn; cannot be worked, ridden or put in the traces until grown.'
      end, 'event');

  elsif p_action = 'use_ancient_file' then
    -- One time in `file_rarity_odds`, a step and no more.
    if random() < 1 / file_rarity_odds() then
      v_rare := rarity_next(c.rare);
      update creature set rare = v_rare where world_id = p_world and id = c.id;
      perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': now ' || v_rare
        || ', blood figures ' || pct_say((select r.blood from rarity_def r where r.id = v_rare))
        || '.', 'event');
    else
      perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': no change. Rarity-up chance: '
        || whole_pct(1 / file_rarity_odds()) || '.', 'event');
    end if;

  elsif p_action = 'use_bronze_mirror' then
    -- The mark, used up at its next covering (`pair_them`).
    update creature set boosts = coalesce(boosts, '{}'::jsonb) || jsonb_build_object('mirror', 1)
     where world_id = p_world and id = c.id;
    perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': '
      || coalesce(mirror_names(mirror_trait(c.traits)), 'nothing') || ' to its next young.', 'event');

  elsif p_action = 'use_ancient_brace' then
    -- One more use, `brace_step` more action speed, up to `brace_most`.
    v_points := brace_points(c) + 1;
    update creature set boosts = coalesce(boosts, '{}'::jsonb) || jsonb_build_object('brace', v_points)
     where world_id = p_world and id = c.id;
    perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': action speed +'
      || whole_pct(brace_step() * v_points) || ' (' || v_points || '/' || brace_most()::int || ').', 'event');

  elsif p_action in ('use_ancient_collar', 'use_ancient_bridle') then
    update creature set boosts = coalesce(boosts, '{}'::jsonb)
        || jsonb_build_object(case when p_action = 'use_ancient_collar' then 'collar' else 'bridle' end, 1)
     where world_id = p_world and id = c.id;
    perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' fitted on ' || c.name || ': '
      || case when p_action = 'use_ancient_collar' then 'upkeep −' || whole_pct(collar_cut())
              else 'speed ridden and in a team +' || whole_pct(bridle_pace()) end || '.', 'event');

  elsif p_action = 'use_ancient_lamp' then
    -- Its lowest-tier trait, one at random of those that share the lowest tier; an empty slot, lower than any trait,
    -- where it has fewer than `trait_slots`, filled as the lowest tier there is (the browser's `rekindle`).
    v_traits := coalesce(c.traits, '{}');
    if coalesce(array_length(v_traits, 1), 0) < trait_slots() then
      v_slot := coalesce(array_length(v_traits, 1), 0) + 1;
      v_was := null;
      v_from := (select t.tier from tier_odds t order by t.ord limit 1);
    else
      select u.i into v_slot from unnest(v_traits) with ordinality u(id, i)
        left join trait_def d on d.id = u.id left join tier_odds t on t.tier = d.tier
       order by coalesce(t.ord, 0), random() limit 1;
      v_was := v_traits[v_slot];
      v_from := coalesce((select d.tier from trait_def d where d.id = v_was), (select t.tier from tier_odds t order by t.ord limit 1));
    end if;
    -- At that tier, or one time in `lamp_tier_odds` the tier above, where there is one.
    v_tier := null;
    if random() < 1 / lamp_tier_odds() then
      select t.tier into v_tier from tier_odds t where t.ord > (select f.ord from tier_odds f where f.tier = v_from) order by t.ord limit 1;
    end if;
    v_up := v_tier is not null;
    v_tier := coalesce(v_tier, v_from);
    -- One it does not carry by name, the one going out included (`lamp_trait`).
    v_now := lamp_trait(v_tier, v_traits);
    if v_now is null then
      perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': nothing kindled.', 'event');
    else
      v_traits[v_slot] := v_now;
      update creature set traits = v_traits where world_id = p_world and id = c.id;
      perform journal_note(p_world, p_uid, 'rekindled');
      perform wtell(p_world, p_uid, lamp_says(c.name, v_name, v_was, v_from, v_now, v_up), 'event');
    end if;

  else
    -- A stat not yet at the most it takes, any of them as likely as another.
    select s into v_stat from unnest(base_stats()) s where pot_points(c, s) < pot_most() order by random() limit 1;
    v_points := pot_points(c, v_stat) + 1;
    update creature set boosts = coalesce(boosts, '{}'::jsonb) || jsonb_build_object(v_stat, v_points)
     where world_id = p_world and id = c.id;
    perform wtell(p_world, p_uid, upper(left(v_name, 1)) || substr(v_name, 2) || ' used on ' || c.name || ': ' || lower(base_stat_name(v_stat))
      || ' ' || pot_says(v_stat, v_points) || '.', 'event');
  end if;
end $function$
